/* Written by context-ds from its brand files. Do not edit; run the CLI again to update. */
:root, .ds-site {
	/* Core */
	--ds-color-brand: #2563EB;
	--ds-color-black: #000000;
	--ds-color-white: #FFFFFF;
	--ds-color-blue-10: #E9EFFD;
	--ds-color-blue-20: #D3E0FB;
	--ds-color-blue-40: #A8C1F7;
	--ds-color-blue-60: #7CA1F3;
	--ds-color-blue-80: #5182EF;
	--ds-color-blue-90: #3B73ED;
	--ds-color-navy-30: #0B1E46;
	--ds-color-neutral-5: #F8F8F8;
	--ds-color-neutral-10: #E6E6E6;
	--ds-color-neutral-20: #CCCCCC;
	--ds-color-neutral-40: #999999;
	--ds-color-neutral-60: #666666;
	--ds-color-neutral-70: #4D4D4D;
	--ds-color-neutral-80: #333333;
	--ds-color-neutral-90: #191919;

	/* Surfaces: white, blue or black, never a gray page */
	--ds-color-bg-default: #FFFFFF;
	--ds-color-bg-subtle: #F8F8F8;
	/* A question card under the pointer (the site's FAQ). */
	--ds-color-bg-card-hover: #F5F5F5;
	--ds-color-bg-frame: #F2F2F2;
	--ds-color-bg-canvas: #FAFAFA;
	--ds-color-bg-tint: #E9EFFD;
	--ds-color-bg-brand: #2563EB;
	--ds-color-bg-inverse: #000000;
	--ds-color-bg-dark: #1A1A1A;
	--ds-color-bg-code: #0D1117;
	/* Syntax colors (the site's GitHub-style theme): on the dark code window, then on light code blocks in articles. */
	--ds-color-code-text: #E6EDF3;
	--ds-color-code-comment: #919BA6;
	--ds-color-code-punctuation: #B1BAC4;
	--ds-color-code-keyword: #D2A8FF;
	--ds-color-code-string: #A5D6FF;
	--ds-color-code-function: #7EE787;
	--ds-color-code-number: #FFA657;
	--ds-color-code-property: #79C0FF;
	--ds-color-code-light-text: #24292F;
	--ds-color-code-light-comment: #656D76;
	--ds-color-code-light-punctuation: #57606A;
	--ds-color-code-light-keyword: #8250DF;
	--ds-color-code-light-string: #0A3069;
	--ds-color-code-light-function: #116329;
	--ds-color-code-light-number: #953800;
	--ds-color-code-light-property: #0550AE;
	--ds-color-bg-scrim: rgb(0 0 0 / 0.1);
	--ds-color-bg-announcement: #F7F8FA;
	/* The benchmark charts' folder-tab bar. */
	--ds-color-bg-tab-bar: #F6F6F7;

	/* Text: black, and black at 65, 60, 55 and 40 percent on white */
	--ds-color-text-default: #000000;
	--ds-color-text-secondary: #595959;
	--ds-color-text-muted: #666666;
	--ds-color-text-subtle: #737373;
	--ds-color-text-nav: #4D4D4D;
	--ds-color-text-faint: #999999;
	--ds-color-text-inverse: #FFFFFF;
	--ds-color-text-brand: #2563EB;
	--ds-color-text-on-brand: #FFFFFF;

	/* Lines */
	--ds-color-border-default: #E6E6E6;
	--ds-color-border-subtle: #F0F0F0;
	--ds-color-border-strong: #CCCCCC;
	--ds-color-border-hairline: rgb(0 0 0 / 0.08);
	--ds-color-border-rule: #E5E7EB;
	--ds-color-border-node: #D1D5DC;
	--ds-color-border-brand: #2563EB;
	--ds-color-border-on-brand: #FFFFFF;
	--ds-color-ring-tint: rgb(37 99 235 / 0.1);
	--ds-color-ring-on-brand: rgb(255 255 255 / 0.3);
	--ds-color-wash-hover: rgb(0 0 0 / 0.04);
	--ds-color-wash-announcement: rgb(0 0 0 / 0.035);
	--ds-color-wash-control: rgb(0 0 0 / 0.05);
	--ds-color-wash-pill: rgb(0 0 0 / 0.06);
	--ds-color-wash-selected: rgb(0 0 0 / 0.07);

	/* Actions and states */
	--ds-color-action-primary: #000000;
	--ds-color-action-primary-hover: #333333;
	--ds-color-action-primary-fg: #FFFFFF;
	--ds-color-status-success: #15803D;
	--ds-color-status-warning: #B45309;
	--ds-color-status-danger: #DC2626;
	/* A status card's text, fill and edge (the dashboard's sidebar status card, dashboard-system.css). */
	--ds-color-status-danger-strong: #B91C1C;
	--ds-color-status-danger-soft: #FEF2F2;
	--ds-color-status-danger-line: #FECACA;
	--ds-color-status-warning-strong: #854D0E;
	--ds-color-status-warning-soft: #FFFBEB;
	--ds-color-status-warning-line: #F4D46C;
	/* The footer's service status dot on near black (the site's emerald-400, amber-400 and red-500). */
	--ds-color-status-success-bright: #00D492;
	--ds-color-status-warning-bright: #FFB900;
	--ds-color-status-danger-bright: #FB2C36;
	/* A cost flag on the compare pages ("25% more", "4x fewer"): a pale amber pill with amber text. */
	--ds-color-bg-caution: #FFFBEB;
	--ds-color-text-caution: #BB4D00;
	--ds-color-focus-ring: #2563EB;
	--ds-color-chart-series-1: #3B82F6;
	--ds-color-chart-series-2: #14B8A6;
	--ds-color-chart-series-3: #F59E0B;
	--ds-color-chart-series-4: #8B5CF6;
	/* The three dots of a code window's title bar. */
	--ds-color-window-close: #FF5F56;
	--ds-color-window-minimize: #FFBD2E;
	--ds-color-window-zoom: #27C93F;
	/* From the dashboard redesign (brand-dev-webapp PR 1045, dashboard-system.css): the full ramps, alerts, the
	   HTTP status chart colors and the skeleton sheen. */
	--ds-color-blue-30: #BED0F9;
	--ds-color-blue-50: #92B1F5;
	--ds-color-blue-70: #6692F1;
	--ds-color-navy-20: #07142F;
	--ds-color-navy-60: #163B8D;
	--ds-color-neutral-30: #B2B2B2;
	--ds-color-neutral-50: #808080;
	--ds-color-alert-strong: #E5484D;
	--ds-color-alert: #F0868A;
	--ds-color-alert-soft: #F7C0C2;
	--ds-color-chart-ok: #22C55E;
	--ds-color-chart-client-error: #F59E0B;
	--ds-color-chart-server-error: #F97316;
	--ds-color-chart-200: #22C55E;
	--ds-color-chart-202: #10B981;
	--ds-color-chart-400: #F59E0B;
	--ds-color-chart-401: #EF4444;
	--ds-color-chart-402: #EC4899;
	--ds-color-chart-404: #F97316;
	--ds-color-chart-409: #EAB308;
	--ds-color-chart-rate-limited: #9A7FE0;
	--ds-color-skeleton-shine: #EDEDED;

	/* Type */
	--ds-font-sans: var(--font-rethink-sans, "Rethink Sans"), system-ui, sans-serif;
	--ds-font-data: var(--font-doto, "Doto"), ui-monospace, monospace;
	/* The site sets code and labels in Rethink Sans too (font-mono on context.dev); the product keeps IBM Plex Mono. */
	--ds-font-mono: var(--font-rethink-sans, "Rethink Sans"), system-ui, sans-serif;
	--ds-font-weight-regular: 400;
	/* The site's medium is 450 (500 in the product, and for Doto, which keeps 500 and 700). */
	--ds-font-weight-medium: 450;
	--ds-font-weight-bold: 600;
	/* Doto figures set heavy, such as a plan's price. */
	--ds-font-weight-heavy: 800;
	/* Doto at its heaviest, for a demo's score figure. */
	--ds-font-weight-score: 900;
	--ds-text-hero: 2.5rem;
	--ds-text-hero-tablet: 48px;
	--ds-text-hero-desktop: 56px;
	--ds-leading-hero: 1.08;
	/* The product hero's title from lg (the Parse, News and ChatGPT pages) and the lead under it: set in px on the site,
	   so they hold their size on the 90% root. The note is the quiet line under the hero's actions. */
	--ds-text-hero-product: 72px;
	--ds-leading-hero-product: 79px;
	--ds-text-lead: 18px;
	--ds-leading-lead: 26px;
	--ds-text-lead-lg: 20px;
	--ds-leading-lead-lg: 28px;
	--ds-text-note: 14px;
	--ds-leading-note: 18px;
	--ds-text-h1: 3.5rem;
	--ds-text-h2: 2.75rem;
	--ds-text-h3: 2rem;
	--ds-text-h4: 1.5rem;
	--ds-text-h5: 1.25rem;
	--ds-text-body-lg: 1.125rem;
	/* A card's description on the landing pages (steps, related products, capability cards), on a 1.5 line. */
	--ds-text-body-md: 0.9375rem;
	/* A FAQ question, and the ask field under the questions (never under 16px, or iOS Safari zooms into it). */
	--ds-text-question: 1.0625rem;
	--ds-text-ask: max(1.0625rem, 16px);
	--ds-text-body: 1rem;
	--ds-text-body-sm: 0.875rem;
	/* A small pill's label, such as the "copy" pill on an article's code block. */
	--ds-text-pill-sm: 0.8125rem;
	--ds-text-caption: 0.75rem;
	/* Chart axis labels (the product's charts). */
	--ds-text-axis: 11px;
	--ds-text-counter: 10px;
	--ds-text-initial: 9px;
	--ds-text-composer: 13.5px;
	--ds-text-stat: 22px;
	--ds-text-metric: 26px;
	/* A product page's hero demo and capability panels (the site's product-demo-card), set in fixed px. */
	--ds-text-demo-glyph: 10px;
	--ds-text-demo-meta: 12px;
	--ds-text-demo-code: 13px;
	--ds-text-demo-label: 14px;
	--ds-text-demo-row: 15px;
	--ds-text-demo-title: 17px;
	--ds-text-demo-score: 56px;
	/* A headline figure on the site, such as the home page's scrape success rate (larger from md). */
	--ds-text-figure: 4rem;
	--ds-text-figure-lg: 5rem;
	--ds-leading-tight: 1.1;
	--ds-leading-heading: 1.2;
	--ds-leading-snug: 1.3;
	/* A FAQ question. */
	--ds-leading-question: 1.375;
	--ds-leading-normal: 1.5;
	--ds-leading-relaxed: 1.625;
	/* Section headings on the site, and code in a window. */
	--ds-leading-display: 1.12;
	--ds-leading-code: 1.7;
	--ds-leading-title: 1.4;
	--ds-leading-field: 1.45;
	--ds-leading-snippet: 1.6;
	--ds-leading-code-card: 1.65;
	/* Code in the site's terminal window: a fixed 22px line at every width (the site sets it in px). */
	--ds-leading-terminal: 22px;
	--ds-leading-badge: 14px;
	/* The demo card's fixed line heights: a status chip, a label, a row title, and a Doto score. */
	--ds-leading-demo-chip: 17px;
	--ds-leading-demo-label: 18px;
	--ds-leading-demo-title: 22px;
	--ds-leading-demo-score: 0.8;
	--ds-leading-type-body: 1.3;
	--ds-leading-type-display: 1.625;
	--ds-leading-type-h3: 1.2;
	--ds-leading-type-h4: 1.2;
	--ds-tracking-tight: -0.035em;
	/* The header menus' titles: the featured product card's name, then the use case preview's name. */
	--ds-tracking-title: -0.03em;
	--ds-tracking-snug: -0.02em;
	/* Section headings set in two colors, such as the FAQ's. */
	--ds-tracking-display: -0.2rem;
	--ds-tracking-normal: 0;
	/* A headline figure, set tighter than a heading. */
	--ds-tracking-figure: -0.045em;
	--ds-tracking-label: 0.08em;

	/* Space (rem, so it follows the root) */
	--ds-space-0: 0;
	--ds-space-px: 1px;
	--ds-space-frame: 6px;
	--ds-space-0-5: 0.125rem;
	--ds-space-1: 0.25rem;
	--ds-space-1-5: 0.375rem;
	--ds-space-2: 0.5rem;
	--ds-space-2-5: 0.625rem;
	--ds-space-3: 0.75rem;
	--ds-space-3-5: 0.875rem;
	--ds-space-4: 1rem;
	--ds-space-5: 1.25rem;
	--ds-space-6: 1.5rem;
	--ds-space-7: 1.75rem;
	--ds-space-8: 2rem;
	--ds-space-9: 2.25rem;
	--ds-space-10: 2.5rem;
	--ds-space-12: 3rem;
	--ds-space-14: 3.5rem;
	--ds-space-16: 4rem;
	--ds-space-20: 5rem;
	--ds-space-24: 6rem;
	--ds-space-32: 8rem;

	/* Layout */
	--ds-layout-column: 68.75rem;
	--ds-layout-column-wide: 81.25rem;
	/* The ruled column's width: full width on phones, 90vw, then min(85vw, column-wide) (site.css). Content containers use it. */
	--ds-frame-column: calc(100% - 2px);
	--ds-layout-text: 36rem;
	--ds-layout-heading: 42rem;
	--ds-layout-sidebar: 212px;
	--ds-layout-parameters: 320px;
	--ds-layout-parameters-header: 32px;
	--ds-layout-product-column: 880px;
	/* The product hero: its headline band's height from md (under the header's), the gap between its lines and the room
	   under its demo, all in px as the site sets them. */
	--ds-layout-product-hero: 520px;
	--ds-layout-product-hero-lead: 640px;
	--ds-layout-product-hero-gap: 22px;
	--ds-layout-product-hero-foot: 88px;

	/* Shape */
	--ds-radius-sm: 0.25rem;
	--ds-radius-tag: 0.375rem;
	--ds-radius-icon: 4px;
	--ds-radius-logo: 5px;
	/* The footer's small Y Combinator mark. */
	--ds-radius-mark: 0.1875rem;
	--ds-radius-snippet: 7px;
	--ds-radius-control: 0.5rem;
	--ds-radius-card: 0.5rem;
	--ds-radius-shell: 0.75rem;
	/* The blue ring around a product page's hero demo: 12px at every root. */
	--ds-radius-demo: 12px;
	--ds-radius-panel: 2.5rem;
	--ds-radius-pill: 9999px;
	--ds-shadow-card: 0 0 0 1px var(--ds-color-border-hairline);
	--ds-shadow-raised: 0 0.25rem 0.5rem rgb(41 41 41 / 0.06), 0 0.125rem 0.25rem rgb(41 41 41 / 0.04), 0 0 0 1px rgb(41 41 41 / 0.08);
	--ds-shadow-floating: 0 0 0 1px rgb(0 0 0 / 0.06), 0 0.5rem 1.5rem -0.5rem rgb(0 0 0 / 0.12);
	--ds-shadow-key: 0 1px 2px rgb(0 0 0 / 0.16);
	--ds-shadow-tooltip: 0 0 0 1px var(--ds-color-border-hairline), 0 4px 12px rgb(0 0 0 / 0.08);
	--ds-shadow-ring-hover: 0 0 0 4px var(--ds-color-ring-tint);
	--ds-shadow-drawer: 0 0 0 1px var(--ds-color-border-hairline), 0 12px 32px rgb(0 0 0 / 0.16);
	/* A band's own bottom rule, inset so it adds no height (the product hero). */
	--ds-shadow-rule-bottom: inset 0 -1px 0 rgb(0 0 0 / 0.1);

	/* Motion: fast UI feedback only, no ease-in */
	--ds-duration-fast: 150ms;
	--ds-duration-base: 200ms;
	--ds-duration-moderate: 250ms;
	--ds-duration-slow: 300ms;
	--ds-easing-out: cubic-bezier(0.22, 1, 0.36, 1);
	--ds-easing-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}

.ds-product {
	--ds-font-mono: var(--font-ibm-plex-mono, "IBM Plex Mono"), ui-monospace, monospace;
	--ds-font-weight-medium: 500;
	--ds-color-bg-default: #FFFFFF;
	--ds-color-text-muted: #4D4D4D;
	--ds-color-text-subtle: #707070;
	--ds-color-border-hairline: rgb(0 0 0 / 0.06);
	--ds-text-display: 56px;
	--ds-text-h3: 28px;
	--ds-text-h4: 21px;
	--ds-text-h5: 18px;
	--ds-text-body-lg: 16px;
	--ds-text-body: 15px;
	--ds-text-body-sm: 12.6px;
	--ds-text-caption: 12px;
	--ds-leading-type-body: 1.3;
	--ds-leading-type-display: 1.15;
	--ds-leading-type-h3: 1.2;
	--ds-leading-type-h4: 1.4;
	--ds-radius-control: 7.5px;
	--ds-radius-card: 10px;
	--ds-radius-shell: 12px;
	--ds-shadow-card: 0 0 0 1px var(--ds-color-border-hairline), 0 1px 1px rgb(0 0 0 / 0.05), 0 2px 4px rgb(0 0 0 / 0.06), 0 4px 14px -4px rgb(0 0 0 / 0.1);
	--ds-shadow-floating: 0 0 0 1px var(--ds-color-border-hairline), 0 0.5rem 1.5rem -0.5rem rgb(0 0 0 / 0.16);
}

:is(.dark, [data-theme="dark"]) .ds-product,
.ds-product:is(.dark, [data-theme="dark"]) {
	--ds-color-brand: #3B73ED;
	--ds-color-bg-default: #151517;
	--ds-color-bg-canvas: #151517;
	--ds-color-bg-subtle: #1C1C1E;
	--ds-color-bg-frame: #0C0C0D;
	--ds-color-bg-tint: #172340;
	--ds-color-bg-brand: #3B73ED;
	--ds-color-bg-scrim: rgb(0 0 0 / 0.5);
	--ds-color-text-default: #F4F4F5;
	--ds-color-text-secondary: #B8B8BD;
	--ds-color-text-muted: #B8B8BD;
	--ds-color-text-subtle: #85858B;
	--ds-color-text-faint: #66666B;
	--ds-color-text-nav: #B8B8BD;
	--ds-color-text-inverse: #000000;
	--ds-color-text-brand: #7CA1F3;
	--ds-color-border-default: #2A2A2D;
	--ds-color-border-subtle: #212124;
	--ds-color-border-strong: #3A3A3E;
	--ds-color-border-hairline: rgb(255 255 255 / 0.07);
	--ds-color-wash-hover: rgb(255 255 255 / 0.04);
	--ds-color-wash-control: rgb(255 255 255 / 0.05);
	--ds-color-wash-pill: rgb(255 255 255 / 0.06);
	--ds-color-wash-selected: rgb(255 255 255 / 0.07);
	--ds-color-action-primary: #F4F4F5;
	--ds-color-action-primary-hover: #D4D4D8;
	--ds-color-action-primary-fg: #000000;
	--ds-color-status-success: #4ADE80;
	--ds-color-status-warning: #FBBF24;
	--ds-color-status-danger: #F87171;
	--ds-color-status-danger-strong: #F87171;
	--ds-color-status-danger-soft: #2D1B1D;
	--ds-color-status-danger-line: #70343B;
	--ds-color-status-warning-strong: #FBBF24;
	--ds-color-status-warning-soft: #2B2517;
	--ds-color-status-warning-line: #6B551D;
	--ds-color-focus-ring: #7CA1F3;
	--ds-color-blue-10: #172340;
	--ds-color-blue-20: #1C2D55;
	--ds-color-blue-30: #233A6D;
	--ds-color-blue-40: #2C4A8A;
	--ds-color-neutral-5: #1C1C1E;
	--ds-color-neutral-10: #2A2A2D;
	--ds-color-neutral-20: #3A3A3E;
	--ds-color-neutral-30: #4D4D52;
	--ds-color-neutral-40: #66666B;
	--ds-color-neutral-50: #808085;
	--ds-color-neutral-60: #9C9CA1;
	--ds-color-neutral-70: #B8B8BD;
	--ds-color-neutral-80: #D4D4D8;
	--ds-color-neutral-90: #ECECEF;
	--ds-color-alert-strong: #F0646A;
	--ds-color-alert: #C9565B;
	--ds-color-alert-soft: #7A3A3E;
	--ds-color-chart-rate-limited: #8A70D6;
	--ds-color-skeleton-shine: #262629;
}

.font-data {
	--ds-font-weight-medium: 500;
	--ds-font-weight-bold: 700;
}

/* Written by context-ds from its brand files. Do not edit; run the CLI again to update. */
@theme inline {
	--color-brand: var(--ds-color-brand);
	--color-black: var(--ds-color-black);
	--color-white: var(--ds-color-white);
	--color-primary: var(--ds-color-action-primary);
	--color-primary-hover: var(--ds-color-action-primary-hover);
	--color-on-primary: var(--ds-color-action-primary-fg);
	--color-focus-ring: var(--ds-color-focus-ring);
	--color-surface: var(--ds-color-bg-default);
	--color-subtle: var(--ds-color-bg-subtle);
	--color-card-hover: var(--ds-color-bg-card-hover);
	--color-frame: var(--ds-color-bg-frame);
	--color-canvas: var(--ds-color-bg-canvas);
	--color-tint: var(--ds-color-bg-tint);
	--color-inverse: var(--ds-color-bg-inverse);
	--color-dark: var(--ds-color-bg-dark);
	--color-code: var(--ds-color-bg-code);
	--color-scrim: var(--ds-color-bg-scrim);
	--color-announcement: var(--ds-color-bg-announcement);
	--color-tab-bar: var(--ds-color-bg-tab-bar);
	--color-fg: var(--ds-color-text-default);
	--color-fg-secondary: var(--ds-color-text-secondary);
	--color-fg-muted: var(--ds-color-text-muted);
	--color-fg-subtle: var(--ds-color-text-subtle);
	--color-fg-faint: var(--ds-color-text-faint);
	--color-fg-nav: var(--ds-color-text-nav);
	--color-fg-inverse: var(--ds-color-text-inverse);
	--color-fg-brand: var(--ds-color-text-brand);
	--color-on-brand: var(--ds-color-text-on-brand);
	--color-line: var(--ds-color-border-default);
	--color-line-subtle: var(--ds-color-border-subtle);
	--color-line-strong: var(--ds-color-border-strong);
	--color-hairline: var(--ds-color-border-hairline);
	--color-rule: var(--ds-color-border-rule);
	--color-node: var(--ds-color-border-node);
	--color-ring-tint: var(--ds-color-ring-tint);
	--color-ring-on-brand: var(--ds-color-ring-on-brand);
	--color-wash-hover: var(--ds-color-wash-hover);
	--color-wash-announcement: var(--ds-color-wash-announcement);
	--color-wash-control: var(--ds-color-wash-control);
	--color-wash-pill: var(--ds-color-wash-pill);
	--color-wash-selected: var(--ds-color-wash-selected);
	--color-success: var(--ds-color-status-success);
	--color-warning: var(--ds-color-status-warning);
	--color-danger: var(--ds-color-status-danger);
	--color-danger-strong: var(--ds-color-status-danger-strong);
